namespace OpenSecurityPlatform.Infrastructure;
public sealed class PostgresModuleExportRepository(string cs) : IModuleExportRepository, IAsyncDisposable { static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web); readonly NpgsqlDataSource _d = NpgsqlDataSource.Create(cs); const string C = "id,tenant_id::text,created_by,state,format,query::text,fields,maximum_records,output_object_id,manifest_object_id,metadata_object_id,created_at,updated_at,expires_at,started_at,completed_at,record_count,output_size,output_sha256,error_code,error_summary"; public async Task<ModuleExportJob> CreateAsync(string t, string a, ModuleExportCreateRequest r, CancellationToken ct) { var id = Guid.NewGuid(); var n = DateTimeOffset.UtcNow; await using var c = await _d.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand("INSERT INTO platform.module_export_jobs(tenant_id,id,created_by,state,format,query,fields,maximum_records,output_object_id,manifest_object_id,metadata_object_id,created_at,updated_at,expires_at)VALUES($1,$2,$3,'pending',$4,$5,$6,$7,$8,$9,$10,$11,$11,$12)", c); q.Parameters.AddWithValue(Guid.Parse(t)); q.Parameters.AddWithValue(id); q.Parameters.AddWithValue(a); q.Parameters.AddWithValue(r.Format); q.Parameters.Add(new() { Value = JsonSerializer.Serialize(r.Query with { Cursor = null }, Json), NpgsqlDbType = NpgsqlDbType.Jsonb }); q.Parameters.AddWithValue(r.Fields ?? []); q.Parameters.AddWithValue(r.MaximumRecords); q.Parameters.AddWithValue(Guid.NewGuid()); q.Parameters.AddWithValue(Guid.NewGuid()); q.Parameters.AddWithValue(Guid.NewGuid()); q.Parameters.AddWithValue(n); q.Parameters.AddWithValue(n.AddMinutes(15)); await q.ExecuteNonQueryAsync(ct); return (await GetAsync(t, id, ct))!; } public async Task<ModuleExportJob?> GetAsync(string t, Guid id, CancellationToken ct) { await using var c = await _d.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand($"SELECT {C} FROM platform.module_export_jobs WHERE tenant_id=$1 AND id=$2", c); q.Parameters.AddWithValue(Guid.Parse(t)); q.Parameters.AddWithValue(id); await using var r = await q.ExecuteReaderAsync(ct); return await r.ReadAsync(ct) ? Read(r) : null; } public async Task<ModuleExportJob?> ClaimAsync(CancellationToken ct) { await using var c = await _d.OpenConnectionAsync(ct); await using var tx = await c.BeginTransactionAsync(IsolationLevel.ReadCommitted, ct); await using var q = new NpgsqlCommand($"WITH x AS(SELECT id FROM platform.module_export_jobs WHERE state='pending' ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1)UPDATE platform.module_export_jobs j SET state='running',started_at=now(),updated_at=now()FROM x WHERE j.id=x.id RETURNING {string.Join(',', C.Split(',').Select(x => "j." + x))}", c, tx); await using var r = await q.ExecuteReaderAsync(ct); var v = await r.ReadAsync(ct) ? Read(r) : null; await r.DisposeAsync(); await tx.CommitAsync(ct); return v; } public async Task CompleteAsync(Guid id, int n, long s, string h, DateTimeOffset at, CancellationToken ct) { await using var c = await _d.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand("UPDATE platform.module_export_jobs SET state='completed',record_count=$2,output_size=$3,output_sha256=$4,completed_at=$5,updated_at=$5 WHERE id=$1", c); q.Parameters.AddWithValue(id); q.Parameters.AddWithValue(n); q.Parameters.AddWithValue(s); q.Parameters.AddWithValue(h); q.Parameters.AddWithValue(at); await q.ExecuteNonQueryAsync(ct); } public async Task FailAsync(Guid id, string code, string s, CancellationToken ct) { await using var c = await _d.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand("UPDATE platform.module_export_jobs SET state='failed',error_code=$2,error_summary=$3 WHERE id=$1", c); q.Parameters.AddWithValue(id); q.Parameters.AddWithValue(code); q.Parameters.AddWithValue(s[..Math.Min(512, s.Length)]); await q.ExecuteNonQueryAsync(ct); } public async Task<IReadOnlyList<ModuleExportJob>> ExpireDueAsync(CancellationToken ct) { await using var c = await _d.OpenConnectionAsync(ct); await using var q = new NpgsqlCommand($"UPDATE platform.module_export_jobs SET state='expired' WHERE state='completed' AND expires_at<=now() RETURNING {C}", c); var l = new List<ModuleExportJob>(); await using var r = await q.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) l.Add(Read(r)); return l; } static ModuleExportJob Read(NpgsqlDataReader r) => new(r.GetGuid(0), r.GetString(1), r.GetString(2), Enum.Parse<FileExportState>(r.GetString(3), true), r.GetString(4), JsonSerializer.Deserialize<ModuleSearchRequest>(r.GetString(5), Json)!, r.GetFieldValue<string[]>(6), r.GetInt32(7), r.GetGuid(8), r.GetGuid(9), r.GetGuid(10), r.GetFieldValue<DateTimeOffset>(11), r.GetFieldValue<DateTimeOffset>(12), r.GetFieldValue<DateTimeOffset>(13), r.IsDBNull(14) ? null : r.GetFieldValue<DateTimeOffset>(14), r.IsDBNull(15) ? null : r.GetFieldValue<DateTimeOffset>(15), r.IsDBNull(16) ? null : r.GetInt32(16), r.IsDBNull(17) ? null : r.GetInt64(17), r.IsDBNull(18) ? null : r.GetString(18), r.IsDBNull(19) ? null : r.GetString(19), r.IsDBNull(20) ? null : r.GetString(20)); public ValueTask DisposeAsync() => _d.DisposeAsync(); }
